// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const AB = new Float64Array( [ 0.0, 2.0, 1.0, 3.0 ] );
	const work = new Float64Array( 2 );

	dlansb(); // $ExpectError
	dlansb( 'column-major' ); // $ExpectError
	dlansb( 'column-major', 'max' ); // $ExpectError
	dlansb( 'column-major', 'max', 'upper' ); // $ExpectError
	dlansb( 'column-major', 'max', 'upper', 2 ); // $ExpectError
	dlansb( 'column-major', 'max', 'upper', 2, 1 ); // $ExpectError
	dlansb( 'column-major', 'max', 'upper', 2, 1, AB ); // $ExpectError
	dlansb( 'column-major', 'max', 'upper', 2, 1, AB, 2 ); // $ExpectError
	dlansb( 'column-major', 'max', 'upper', 2, 1, AB, 2, work, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	const AB = new Float64Array( [ 0.0, 2.0, 1.0, 3.0 ] );
	const work = new Float64Array( 2 );

	dlansb.ndarray( 'max', 'upper', 2, 1, AB, 1, 2, 0, work, 1, 0 ); // $ExpectType number
}

