// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const AB = new Float64Array( [ 0.0, 2.0, 1.0, 3.0 ] );
	const work = new Float64Array( 2 );

	dlansb.ndarray(); // $ExpectError
	dlansb.ndarray( 'max' ); // $ExpectError
	dlansb.ndarray( 'max', 'upper' ); // $ExpectError
	dlansb.ndarray( 'max', 'upper', 2 ); // $ExpectError
	dlansb.ndarray( 'max', 'upper', 2, 1 ); // $ExpectError
	dlansb.ndarray( 'max', 'upper', 2, 1, AB ); // $ExpectError
	dlansb.ndarray( 'max', 'upper', 2, 1, AB, 1 ); // $ExpectError
	dlansb.ndarray( 'max', 'upper', 2, 1, AB, 1, 2 ); // $ExpectError
	dlansb.ndarray( 'max', 'upper', 2, 1, AB, 1, 2, 0 ); // $ExpectError
	dlansb.ndarray( 'max', 'upper', 2, 1, AB, 1, 2, 0, work ); // $ExpectError
	dlansb.ndarray( 'max', 'upper', 2, 1, AB, 1, 2, 0, work, 1 ); // $ExpectError
	dlansb.ndarray( 'max', 'upper', 2, 1, AB, 1, 2, 0, work, 1, 0, 10 ); // $ExpectError
}
